={{ (() => {
    const pages = $json.pages.map(p => p.data).sort((a, b) => a.pageIndex - b.pageIndex);
    const fmt = s => {
      s = Math.max(0, s);
      const h = String(Math.floor(s/3600)).padStart(2,'0');
      const m = String(Math.floor((s%3600)/60)).padStart(2,'0');
      const sec = String(Math.floor(s%60)).padStart(2,'0');
      const ms = String(Math.round((s%1)*1000)).padStart(3,'0');
      return h+':'+m+':'+sec+','+ms;
    };
    const chunks = [];
    let offset = 0, idx = 1;
    for (const page of pages) {
      const words = page.timestamps.filter(t => t.word.trim() && !/^[.,!?;:]$/.test(t.word.trim()));
      let i = 0;
      while (i < words.length) {
        const blockStart = words[i].start_time;
        let blockEnd = words[i].end_time;
        let chunkWords = [words[i].word.trim()];
        i++;
        while (i < words.length) {
          const dur = words[i].end_time - blockStart;
          if (dur > 7) break;
          chunkWords.push(words[i].word.trim());
          blockEnd = words[i].end_time;
          i++;
          if (dur >= 2 && chunkWords.length >= 5) break;
        }
        chunks.push({ idx, start: fmt(blockStart+offset), end: fmt(blockEnd+offset), text: chunkWords.join(' ') });
        idx++;
      }
      offset += page.timestamps[page.timestamps.length-1].end_time;
    }
    return chunks;
  })() }}

={{ (() => {
    const pages = $json.pages
      .map(p => p.data)
      .sort((a, b) => a.pageIndex - b.pageIndex);

    let meta = ';FFMETADATA1\n', offset = 0;

    for (const page of pages) {
      const dur = page.timestamps[page.timestamps.length - 1].end_time;
      meta += `\n[CHAPTER]\nTIMEBASE=1/1000\nSTART=${Math.round(offset * 1000)}\nEND=${Math.round((offset + dur) * 1000)}\ntitle=Page ${page.pageIndex + 1}\n`;
      offset += dur;
    }

    return meta;
  })() }}

={{ (() => {
    const chunks = $json.chunks;
    let srt = '';
    for (const c of chunks) {
      const words = c.json.text.split(' ');
      const mid = Math.ceil(words.length / 2);
      const line1 = words.slice(0, mid).join(' ');
      const line2 = words.slice(mid).join(' ');
      const text = line2 ? line1 + '\n' + line2 : line1;
      srt += c.json.idx + '\n' + c.json.start + ' --> ' + c.json.end + '\n' + text + '\n\n';
    }
    return srt.trim();
  })() }}
